// Compact month + day agenda inspired by Apple/Google Calendar.
// Surfaces/radii and restrained elevation reference MagicPath theme 5000.
let mobileSelectedDate=iso(today);
const isMobileCalendar=()=>window.matchMedia('(max-width:700px)').matches;
function mobileCalendarDates(){if(view==='month'){const first=new Date(cursor.getFullYear(),cursor.getMonth(),1),last=new Date(cursor.getFullYear(),cursor.getMonth()+1,0),start=addDays(first,-first.getDay());return Array.from({length:Math.ceil((first.getDay()+last.getDate())/7)*7},(_,i)=>addDays(start,i))}return datesForView()}
function mobileDateButton(d){
  const s=iso(d),ts=tasksForDay(s),selected=s===mobileSelectedDate;
  return `<button type="button" class="mobile-date ${selected?'selected':''} ${s===iso(today)?'is-today':''} ${view==='month'&&d.getMonth()!==cursor.getMonth()?'outside':''}" data-mobile-date="${s}" aria-pressed="${selected}" aria-label="${d.toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}, ${ts.length} tarefas pendentes"><span class="mobile-weekname">${d.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}</span><span class="mobile-daynumber">${d.getDate()}</span><span class="mobile-dots" aria-hidden="true">${ts.slice(0,3).map(t=>`<i style="background:${taskColor(t)}"></i>`).join('')}${ts.length>3?'<b>+</b>':''}</span>${view==='month'?`<span class="mobile-cell-events">${ts.slice(0,2).map(t=>`<span class="mobile-cell-label" style="--label-color:${taskColor(t)}">${esc(t.emoji||'📌')} ${esc(t.name)}</span>`).join('')}${ts.length>2?`<span class="mobile-cell-overflow">+${ts.length-2}</span>`:''}</span>`:''}</button>`;
}
function mobileAgendaTask(t){
  return `<article class="mobile-event" style="--event-color:${taskColor(t)}"><span class="mobile-event-icon" aria-hidden="true">${esc(t.emoji||'📌')}</span><button class="mobile-event-content" data-task="${t.id}"><strong>${esc(t.name)}</strong><small>${esc(category(t.category)?.name||'Tarefa')}${t.end?' · até '+fmt(t.end):''}</small>${t.description?`<span>${esc(t.description)}</span>`:''}</button><button class="check" data-check="${t.id}" aria-label="Concluir ${esc(t.name)}"></button></article>`;
}
function mobileCalendar(){
  const dates=mobileCalendarDates();
  if(view!=='year'&&!dates.some(d=>iso(d)===mobileSelectedDate))mobileSelectedDate=iso(view==='month'?cursor:dates[0]);
  const selected=parse(mobileSelectedDate),ts=tasksForDay(mobileSelectedDate),period=view==='year'?String(cursor.getFullYear()):`${months[cursor.getMonth()]} <span>${cursor.getFullYear()}</span>`;
  return `<div class="mobile-calendar"><div class="mobile-cal-topbar"><button id="mobileyear" aria-label="Ver calendário anual">‹ <span>${cursor.getFullYear()}</span></button><div><button id="today">Hoje</button><button id="mobilequickadd" aria-label="Adicionar tarefa no dia selecionado">＋</button></div></div><header class="mobile-cal-header"><div><span class="mobile-eyebrow">SEU CALENDÁRIO</span><h1>${view==='year'?cursor.getFullYear():months[cursor.getMonth()]}</h1></div></header><div class="mobile-viewbar" role="group" aria-label="Visualização do calendário">${[['month','Mês'],['week','Semana'],['fortnight','15 dias'],['day','Dia'],['year','Ano']].map(([v,t])=>`<button data-view="${v}" class="${view===v?'active':''}" aria-pressed="${view===v}">${t}</button>`).join('')}</div><section class="mobile-cal-surface"><div class="mobile-periodbar"><button id="prev" aria-label="Período anterior">‹</button><button id="mobileperiod" class="mobile-period-title" aria-label="Escolher mês, ano ou data">${period}<span class="mobile-period-chevron">⌄</span></button><button id="next" aria-label="Próximo período">›</button></div>${view==='year'?`<div id="calendargrid" class="mobile-yeargrid">${months.map((m,i)=>`<button data-month="${i}" class="mobile-monthbox"><strong>${m}</strong><small>${pending().filter(t=>(!calCat||t.category===calCat)&&t.date<=iso(new Date(cursor.getFullYear(),i+1,0))&&(t.end||t.date)>=iso(new Date(cursor.getFullYear(),i,1))).length} tarefas</small></button>`).join('')}</div>`:`${view==='month'?'<div class="mobile-weekdays">'+['D','S','T','Q','Q','S','S'].map(n=>`<span>${n}</span>`).join('')+'</div>':''}<div id="calendargrid" class="mobile-dategrid view-${view}" aria-label="Dias do período">${dates.map(mobileDateButton).join('')}</div><p class="mobile-swipe-hint">Deslize para mudar ${view==='month'?'o mês':view==='week'?'a semana':'o período'}</p>`}</section><details class="mobile-calendar-filters" ${calCat?'open':''}><summary><span>${icon('settings')} Filtros e escala</span><span>${calCat?esc(category(calCat)?.name||'Categoria'):'Todas as categorias'} ⌄</span></summary><div><label>Mostrar tarefas de<select id="calcat"><option value="">Todas as categorias</option>${db.categories.map(c=>`<option value="${c.id}" ${calCat===c.id?'selected':''}>${esc(c.emoji+' '+c.name)}</option>`).join('')}</select></label><button id="importcalendar">🧹 Importar escala por foto</button></div></details>${view==='year'?'<p class="mobile-year-hint">Toque em um mês para ver os dias e as tarefas.</p>':`<section class="mobile-agenda" aria-label="Tarefas do dia selecionado"><div class="mobile-agenda-heading"><div><span>${mobileSelectedDate===iso(today)?'HOJE':selected.toLocaleDateString('pt-BR',{weekday:'long'}).toUpperCase()}</span><h2>${selected.toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</h2></div><span class="mobile-task-count">${ts.length} ${ts.length===1?'tarefa':'tarefas'}</span></div>${ts.length?ts.map(mobileAgendaTask).join(''):`<div class="mobile-agenda-empty"><span aria-hidden="true">☀️</span><strong>Um dia livre por aqui</strong><p>Um espaço para descansar ou planejar algo.</p><button id="mobileemptyadd">Adicionar tarefa neste dia</button></div>`}</section>`}<button class="mobile-cal-fab" id="newtask" aria-label="Adicionar tarefa ${fmt(mobileSelectedDate)}"><span aria-hidden="true">＋</span> Nova tarefa</button></div>`;
}
function bindMobileCalendar(){
  if(page!=='calendar'||!isMobileCalendar())return;
  document.querySelectorAll('[data-mobile-date]').forEach(b=>b.onclick=()=>{mobileSelectedDate=b.dataset.mobileDate;if(view==='day')cursor=parse(mobileSelectedDate);render();if(view==='month')dayModal(mobileSelectedDate)});
  const add=()=>taskForm(null,view==='year'?iso(cursor):mobileSelectedDate);$('#newtask').onclick=add;$('#mobilequickadd').onclick=add;$('#mobileyear').onclick=()=>{view='year';render()};if($('#mobileemptyadd'))$('#mobileemptyadd').onclick=add;
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(view!=='year')cursor=parse(mobileSelectedDate);view=b.dataset.view;render()});
  $('#today').onclick=()=>{cursor=new Date(today);mobileSelectedDate=iso(today);render()};
  $('#mobileperiod').onclick=()=>{
    modal(`<h2>Escolher período</h2><form id="mobileperiodform" class="form"><div class="pair"><label>Mês<select name="month">${months.map((m,i)=>`<option value="${i}" ${cursor.getMonth()===i?'selected':''}>${m}</option>`).join('')}</select></label><label>Ano<input name="year" type="number" min="1900" max="2200" required value="${cursor.getFullYear()}"></label></div><label>Ou ir direto a uma data<input name="date" type="date"></label><div class="modal-actions"><button type="button" id="cancelperiod">Cancelar</button><button class="primary">Mostrar período</button></div></form>`);
    $('#cancelperiod').onclick=close;$('#mobileperiodform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);cursor=f.get('date')?parse(f.get('date')):new Date(+f.get('year'),+f.get('month'),1);mobileSelectedDate=iso(cursor);close();render()};
  };
}
const calendarDesktop=calendar;
calendar=function(){return isMobileCalendar()?mobileCalendar():calendarDesktop()};
